/**
 * @param {number[]} arr
 * @param {number} target
 * @return {number}
 */
var minSumOfLengths = function(arr, target) {
    const n = arr.length;
    let res = [];

    for (let i = 0; i < n; i++) {
        let sum = 0;
        let count = 0;

        for (let j = i; j < n; j++) {
            sum += arr[j];
            count++;

            if (sum >= target) break;
        }

        if (sum === target) {
            res.push(count);
        }
    }

    if (res.length < 2) return -1;

    res.sort((a, b) => a - b);

    return res[0] + res[1];
};

/** By Leetcode */
var minSumOfLengths = function (arr, target) {
    const n = arr.length;
    const dp = Array(n + 1).fill(n);
    let res = n + 1;
    let sum = 0;
    let left = 0;

    for (let right = 0; right < n; right++) {
        sum += arr[right];

        while (sum > target) {
            sum -= arr[left];
            left++;
        }

        dp[right + 1] = dp[right];

        if (sum === target) {
            const length = right - left + 1;
            res = Math.min(res, length + dp[left]);
            dp[right + 1] = Math.min(dp[right], length);
        }
    }

    return res === n + 1 ? -1 : res;
};
